css:
#loader-22 {
  display: inline-grid;
  width: 80px;
  aspect-ratio: 1;
}
#loader-22:before,
#loader-22:after {
  content: '';
  grid-area: 1/1;
  border-radius: 50%;
}
#loader-22:before {
  margin: 25%;
  background: repeating-conic-gradient(#C02942 0 60deg,#0B486B 0 120deg);
  transform: rotate(0turn) translate(50%) rotate(0turn);
  animation: l2 2s alternate infinite ease-in-out;
}
#loader-22:after {
  padding: 10%;
  margin: -10%;
  background: repeating-conic-gradient(from -15deg,#C02942 0 30deg,#0B486B 0 60deg);
  mask: conic-gradient(from 75deg,#000 210deg,#0000 0) content-box exclude,conic-gradient(from 75deg,#000 210deg,#0000 0);
}
@keyframes l2 {
  to{transform: rotate(.5turn) translate(50%) rotate(-1turn)}
}
